let shadowRoot;
let hostElement;

const setHostElement = (element) => {
    hostElement = element;
    // also set the shadowRoot for convenience
    shadowRoot = element.shadowRoot
}

const sleep = (ms=1500) => {
  return new Promise(resolve => setTimeout(resolve, ms));
}

const showElement = (selector, displayType='block', ancestor=shadowRoot ) => {
    getElement(selector, ancestor).style.display = displayType
}

const hideElement = (selector, ancestor=shadowRoot) => {
    getElement(selector, ancestor).style.display = 'none'
}

